template<ll mod>class modint{
public:
    ll a;
    constexpr modint(ll x=0):a(((x%mod)+mod)%mod){}
    constexpr ll&value(){return a;}
    constexpr const ll&value()const{return a;}
    constexpr modint operator-()const{return modint()-*this;}
    constexpr modint&operator++(){if(++a==mod)a=0;return *this;}
    constexpr modint&operator--(){if(!a)a=mod;--a;return *this;}
    constexpr modint&operator+=(const modint&r){a+=r.a;if(a>=mod)a-=mod;return *this;}
    constexpr modint&operator-=(const modint&r){if(a<r.a)a+=mod;a-=r.a;return *this;}
    constexpr modint&operator*=(const modint&r){a=a*r.a%mod;return *this;}
    constexpr modint&operator/=(const modint&r){a=a*inv(r.a).a%mod;return *this;}
    constexpr modint pow(ll n)const{modint x=*this,r=1;while(n){if(n&1)r*=x;x*=x;n>>=1;}return r;}
    constexpr modint inv()const{return pow(mod-2);}
    friend modint operator+(const modint&l,const modint&r){return modint(l)+=r;}
    friend modint operator-(const modint&l,const modint&r){return modint(l)-=r;}
    friend modint operator*(const modint&l,const modint&r){return modint(l)*=r;}
    friend modint operator/(const modint&l,const modint&r){return modint(l)/=r;}
