template<typename T>struct Matrix{
    vector<vector<T>>A;
    Matrix()=default;
    Matrix(size_t n,size_t m):A(n,vector<T>(m,0)){}
    Matrix(size_t n):A(n,vector<T>(n,0)){}
    size_t height()const{return A.size();}
    size_t width()const{return A.empty()?0:A[0].size();}
    const vector<T>&operator[](int k)const{return A.at(k);}
    vector<T>&operator[](int k){return A.at(k);}
    static Matrix I(size_t n){Matrix m(n);for(size_t i=0;i<n;i++)m[i][i]=1;return m;}
    Matrix&operator+=(const Matrix&B){size_t n=height(),m=width();assert(n==B.height()&&m==B.width());for(size_t i=0;i<n;i++)for(size_t j=0;j<m;j++)A[i][j]+=B[i][j];return *this;}
    Matrix&operator-=(const Matrix&B){size_t n=height(),m=width();assert(n==B.height()&&m==B.width());for(size_t i=0;i<n;i++)for(size_t j=0;j<m;j++)A[i][j]-=B[i][j];return *this;}
    Matrix&operator*=(const Matrix&B){size_t n=height(),m=B.width(),p=width();assert(p==B.height());vector<vector<T>>C(n,vector<T>(m,0));for(size_t i=0;i<n;i++)for(size_t j=0;j<m;j++)for(size_t k=0;k<p;k++)C[i][j]+=A[i][k]*B[k][j];A=move(C);return *this;}
    Matrix&operator^=(long long k){Matrix B=Matrix::I(height());while(k>0){if(k&1)B*=*this;*this*=*this;k>>=1LL;}A=move(B.A);return *this;}
    Matrix operator+(const Matrix&B)const{return Matrix(*this)+=B;}
    Matrix operator-(const Matrix&B)const{return Matrix(*this)-=B;}
    Matrix operator*(const Matrix&B)const{return Matrix(*this)*=B;}
    Matrix operator^(long long k)const{return Matrix(*this)^=k;}
    friend ostream&operator<<(ostream&os,const Matrix&p){size_t n=p.height(),m=p.width();for(size_t i=0;i<n;i++){os<<"[";for(size_t j=0;j<m;j++)os<<p[i][j]<<(j+1==m?"]\n":",");}return os;}
    T determinant(){
        Matrix B(*this);
        assert(width()==height());
        T ret=1;
        for(size_t i=0;i<width();i++){
            int idx=-1;
            for(size_t j=i;j<width();j++)if(B[j][i]!=0){idx=j;break;}
            if(idx==-1)return 0;
            if(i!=idx){ret*=-1;swap(B[i],B[idx]);}
            ret*=B[i][i];
            T vv=B[i][i];
            for(size_t j=0;j<width();j++)B[i][j]/=vv;
            for(size_t j=i+1;j<width();j++){
                T a=B[j][i];
                for(size_t k=0;k<width();k++)B[j][k]-=B[i][k]*a;
            }
        }
        return ret;
    }
};
